1	const PROCESSING_FEE = 5;
2	const FIRST_INSURANCE_SURCHARGE_RATE = 0.1;
3	const CURSE_SURCHARGE_RATE = 0.5;
4	const HIGH_ENCHANTMENT_SURCHARGE_RATE = 0.3;
5	const HIGH_ENCHANTMENT_THRESHOLD = 5;
6	const LOYALTY_DISCOUNT_RATE = 0.2;
7	const LOYALTY_YEARS_THRESHOLD = 2;
8	const FOLLOW_UP_DISCOUNT_RATE = 0.15;
9	
10	const COMPONENT_BASE_PREMIUM = 25;
11	const BLOCK_SIZE = 3;
12	const BLOCK_PREMIUM = 60;
13	
14	const DEDUCTIBLE = 100;
15	const CAP_MULTIPLIER = 2;
16	const REIMBURSEMENT_HIGH_ENCHANTMENT_THRESHOLD = 8;
17	const REIMBURSEMENT_HIGH_ENCHANTMENT_RATE = 0.5;
18	
19	const BASE_PREMIUM: Record<string, number> = {
20	  sword: 100,
21	  amulet: 60,
22	  staff: 80,
23	  potion: 40,
24	  rune: COMPONENT_BASE_PREMIUM,
25	  moonstone: COMPONENT_BASE_PREMIUM,
26	};
27	
28	const INSURANCE_VALUE: Record<string, number> = {
29	  sword: 1000,
30	  amulet: 600,
31	  staff: 800,
32	  potion: 400,
33	  rune: 250,
34	  moonstone: 250,
35	};
36	
37	const COMPONENT_TYPES = new Set(["rune", "moonstone"]);
38	
39	type Item = { type: string; cursed?: boolean; enchantment?: number; material?: string };
40	type Customer = { yearsWithMHPCO: number };
41	type Damage = { itemType: string; amount: number };
42	type QuoteStep = { op: "quote"; items: Item[] };
43	type ClaimStep = {
44	  op: "claim";
45	  policy: number;
46	  incident: { cause: string; damages: Damage[] };
47	};
48	type Step = QuoteStep | ClaimStep;
49	type Scenario = { customer: Customer; steps: Step[] };
50	
51	type QuoteResult = { premium: number };
52	type ClaimResult = { payout: number; remainingCap: number };
53	type StepResult = QuoteResult | ClaimResult;
54	
55	type PolicyState = { items: Item[]; insuranceSum: number; remainingCap: number };
56	
57	const countsByType = (items: Item[]): Map<string, number> =>
58	  items.reduce(
59	    (counts, item) => counts.set(item.type, (counts.get(item.type) ?? 0) + 1),
60	    new Map<string, number>(),
61	  );
62	
63	const groupBase = (type: string, count: number): number =>
64	  COMPONENT_TYPES.has(type) && count === BLOCK_SIZE
65	    ? BLOCK_PREMIUM
66	    : count * BASE_PREMIUM[type];
67	
68	const itemsBase = (items: Item[]): number =>
69	  [...countsByType(items)].reduce(
70	    (total, [type, count]) => total + groupBase(type, count),
71	    0,
72	  );
73	
74	const isCursed = (item: Item): boolean => item.cursed === true;
75	const isHighlyEnchanted = (item: Item): boolean =>
76	  (item.enchantment ?? 0) >= HIGH_ENCHANTMENT_THRESHOLD;
77	
78	const itemSurcharge = (item: Item): number => {
79	  const base = BASE_PREMIUM[item.type];
80	  const curseSurcharge = isCursed(item) ? base * CURSE_SURCHARGE_RATE : 0;
81	  const highEnchantmentSurcharge = isHighlyEnchanted(item)
82	    ? base * HIGH_ENCHANTMENT_SURCHARGE_RATE
83	    : 0;
84	  return curseSurcharge + highEnchantmentSurcharge;
85	};
86	
87	const itemSurchargesTotal = (items: Item[]): number =>
88	  items.reduce((sum, item) => sum + itemSurcharge(item), 0);
89	
90	const roundUpInFavorOfInsurer = (amount: number): number =>
91	  Math.ceil(Math.round(amount * 1e6) / 1e6);
92	
93	const roundDownInFavorOfInsurer = (amount: number): number =>
94	  Math.floor(Math.round(amount * 1e6) / 1e6);
95	
96	const isLoyal = (customer: Customer): boolean =>
97	  customer.yearsWithMHPCO >= LOYALTY_YEARS_THRESHOLD;
98	
99	const loyaltyDiscount = (customer: Customer, policyBase: number): number =>
100	  isLoyal(customer) ? policyBase * LOYALTY_DISCOUNT_RATE : 0;
101	
102	const firstInsuranceSurcharge = (policyBase: number): number =>
103	  policyBase * FIRST_INSURANCE_SURCHARGE_RATE;
104	
105	const followUpDiscount = (policyBase: number, isFollowUp: boolean): number =>
106	  isFollowUp ? policyBase * FOLLOW_UP_DISCOUNT_RATE : 0;
107	
108	const validateItems = (items: Item[]): void => {
109	  const unknown = items.find((item) => !(item.type in BASE_PREMIUM));
110	  if (unknown) throw new Error(`unknown item type: ${unknown.type}`);
111	};
112	
113	const quotePremium = (items: Item[], customer: Customer, isFollowUp: boolean): number => {
114	  validateItems(items);
115	  const policyBase = itemsBase(items);
116	  return roundUpInFavorOfInsurer(
117	    policyBase +
118	      itemSurchargesTotal(items) +
119	      firstInsuranceSurcharge(policyBase) -
120	      loyaltyDiscount(customer, policyBase) -
121	      followUpDiscount(policyBase, isFollowUp) +
122	      PROCESSING_FEE,
123	  );
124	};
125	
126	const insuranceSum = (items: Item[]): number =>
127	  items.reduce((sum, item) => sum + INSURANCE_VALUE[item.type], 0);
128	
129	const createPolicy = (items: Item[]): PolicyState => {
130	  const sum = insuranceSum(items);
131	  return { items, insuranceSum: sum, remainingCap: sum * CAP_MULTIPLIER };
132	};
133	
134	const reimbursementRate = (item: Item): number =>
135	  (item.enchantment ?? 0) >= REIMBURSEMENT_HIGH_ENCHANTMENT_THRESHOLD
136	    ? REIMBURSEMENT_HIGH_ENCHANTMENT_RATE
137	    : 1;
138	
139	const damagePayout = (damage: Damage, damagedItem: Item): number =>
140	  damage.amount * reimbursementRate(damagedItem) - DEDUCTIBLE;
141	
142	const findDamagedItem = (policy: PolicyState, itemType: string): Item =>
143	  policy.items.find((i) => i.type === itemType)!;
144	
145	const payoutForDamage = (policy: PolicyState, damage: Damage): number =>
146	  damagePayout(damage, findDamagedItem(policy, damage.itemType));
147	
148	const validateDamages = (damages: Damage[]): void => {
149	  const negative = damages.find((damage) => damage.amount < 0);
150	  if (negative) throw new Error(`negative damage amount: ${negative.amount}`);
151	};
152	
153	const totalDesiredPayout = (policy: PolicyState, damages: Damage[]): number =>
154	  damages.reduce((sum, damage) => sum + payoutForDamage(policy, damage), 0);
155	
156	const processClaim = (policy: PolicyState, damages: Damage[]): ClaimResult => {
157	  validateDamages(damages);
158	  const desired = totalDesiredPayout(policy, damages);
159	  const payout = roundDownInFavorOfInsurer(Math.min(desired, policy.remainingCap));
160	  policy.remainingCap -= payout;
161	  return { payout, remainingCap: policy.remainingCap };
162	};
163	
164	export const runScenario = (scenario: unknown): unknown => {
165	  const s = scenario as Scenario;
166	  const policies = new Map<number, PolicyState>();
167	  let quoteCount = 0;
168	  const results: StepResult[] = s.steps.map((step, index) => {
169	    if (step.op === "quote") {
170	      const isFollowUp = quoteCount > 0;
171	      quoteCount += 1;
172	      policies.set(index, createPolicy(step.items));
173	      return { premium: quotePremium(step.items, s.customer, isFollowUp) };
174	    }
175	    const policy = policies.get(step.policy)!;
176	    return processClaim(policy, step.incident.damages);
177	  });
178	  return { results };
179	};
